const { userInfo } = require("os");
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 3) {
    let [m, n, r] = lines[0].split(" ").map((ele) => parseInt(ele));
    let a = lines[1].split(" ").map(Number);
    let b = lines[2].split(" ").map(Number);
    getResult(a, b, r);
    lines.length = 0;
  }
});

function getResult(a, b, r) {
  for (let ai of a) {
    const j = binarySearch(b, ai);
    if (j >= 0) {
      console.log(`${ai} ${b[j]}`);
    } else {
      const insertIdx = -j - 1;
      if (insertIdx == b.length) continue;
      if (b[insertIdx] - ai <= r) console.log(`${ai} ${b[insertIdx]}`);
    }
  }
}

function binarySearch(arr, target) {
  let low = 0;
  let high = arr.length - 1;

  while (low <= high) {
    const mid = (low + high) >> 1;
    const midVal = arr[mid];

    if (midVal > target) {
      high = mid - 1;
    } else if (midVal < target) {
      low = mid + 1;
    } else {
      return mid;
    }
  }

  return -low - 1;
}

