#include <stdio.h>

int binarySearch(const int nums[], int nums_size, int key) {
    int low = 0;
    int high = nums_size - 1;

    while(low <= high) {
        int mid = (low + high) >> 1;
        int midVal = nums[mid];

        if(midVal > key) {
            high = mid - 1;
        } else if(midVal < key) {
            low = mid + 1;
        } else {
            return mid;
        }
    }

    return -low - 1;
}

